            HistoryText(catalog,"baselineCovered","Initial history verified by server: {0}.","Historial inicial verificado por el servidor: {0}.","Storico iniziale verificato dal server: {0}.","服务器已验证的初始历史操作：{0}。");
            HistoryText(catalog,"publicationState","Operations saved here: {0}. Pending: {1}. Confirmed by server: {2}. Attention required: {3}. Original operations awaiting verified registration: {4}. Last confirmed server revision: {5}.","Operaciones guardadas aquí: {0}. Pendientes: {1}. Confirmadas por servidor: {2}. Requieren atención: {3}. Operaciones originales pendientes de registro verificado: {4}. Última revisión confirmada: {5}.","Operazioni salvate qui: {0}. In attesa: {1}. Confermate dal server: {2}. Da verificare: {3}. Operazioni originali in attesa di registrazione verificata: {4}. Ultima revisione confermata dal server: {5}.","本机已保存操作：{0}。待发送：{1}。服务器已确认：{2}。需处理：{3}。等待验证登记的原始操作：{4}。服务器最近确认版本：{5}。");
