            HistoryText(catalog,"receptionState","Received history revision {0}, last complete reception {1}. {2}","Revisión del historial recibida: {0}; última recepción completa: {1}. {2}","Revisione storico ricevuta: {0}; ultima ricezione completa: {1}. {2}","已收到历史版本 {0}，最近完整接收时间：{1}。{2}");
